<asy>
size(250);
pair A,B,C,D,O,E,F,G,H,K;
A = (0,0);
B = (900,0);
C = (900,900);
D = (0,900);
O = (450,450);
E = (600,0);
F = (150,0);
G = (-600,0);
H = (450,0);
K = (0,270);
draw(A--B--C--D--cycle);
draw(O--E);
