=== Solution 1 ===
<center><asy>
size(250); defaultpen(0.70 + fontsize(10)); import olympiad;
pair O = (0,0), B = O - (9,0), A= O + (9,0), C=A+(18,0), T = 9 * expi(-1.2309594), P = foot(A,C,T);
draw(Circle(O,9)); draw(B--C--T--O); draw(A--P); dot(A); dot(B); dot(C); dot(O); dot(T); dot(P);
