for (int i = 0; i < 8; i+=1) {
if (pts[i] == 0) {
dot(vertices[i], blue+5);
}
if (pts[i] == 1) {
dot(vertices[i], red+5);
}
}
};
int[] sus = {0,0,0,0,1,1,1,1};
oct11(sus);
</asy>

