pair B2 = (-0.5,0.5);
pair B3 = (-0.5,-0.5);
pair B4 = (0.5,-0.5);
dot(B1);
dot(B2);
dot(B3);
dot(B4);
draw(A1--A5--A7--A11--cycle);
