draw((0,3)--(0,-3),linetype("2.5 2.5")+linewidth(.5));
draw((3,0)--(-3,0),linetype("2.5 2.5")+linewidth(.5));
label('$w$',(-1,-1),SW);
label('$w$',(1,-1),SE);
draw((4.5,0)--(6.5,2)--(8.5,0)--(6.5,-2)--cycle);
