draw((-3,0)--(-3,3)--(0,3),linewidth(.5));
draw((0,2)--(-1,3)--(-3,1)--(-2,0),dashed+linewidth(.5));
draw((0,2)--(-2,0),linewidth(.5));
draw((0,3)--(0,0),linetype("2.5 2.5")+linewidth(.5));
draw((0,0)--(-3,0),linetype("2.5 2.5")+linewidth(.5));
label("$w$",(-1,1),NW);
label("$w$",(-2,2),SE);
label("$h$",(-2.5,0.5),NE);
label("$h$",(-0.5,2.5),SW);
label("$\frac{w}{\sqrt{2}}$",(-2,3),N);
