        ds((1,1));
        ds((2,1));
        ds((3,1));
        ds((1,3));

        for (int i = 0; i <= 5; ++i) {
            draw((0,i)--(5,i));
            draw((i,0)--(i,5));
        }

        label("Initial", (2.5,-1));
        draw((6,2.5)--(8,2.5),Arrow);

        ds((10,2));
        ds((11,1));
        ds((11,0));

        for (int i = 0; i <= 5; ++i) {
            draw((9,i)--(14,i));
            draw((i+9,0)--(i+9,5));
