    }

ds((10,3));
ds((12,3));
ds((11,1));

for (int i = 0; i <= 5; ++i) {
    draw((9,i)--(14,i));
    draw((i+9,0)--(i+9,5));
    }

ds((19,3));
ds((20,1));
ds((21,2));

for (int i = 0; i <= 5; ++i) {
    draw((18,i)--(23,i));
    draw((i+18,0)--(i+18,5));
    }

ds((28,3));
ds((29,1));
ds((30,1));

for (int i = 0; i <= 5; ++i) {
    draw((27,i)--(32,i));
    draw((i+27,0)--(i+27,5));
    }

