{
  for (real i = 1; i < yMax; ++i)
  {
    draw((-1/32,i)--(1/32,i), black+linewidth(1));
  }
}

//Draws the vertical ticks
void verticalTicks()
{
  for (real i = 1; i < xMax; ++i)
  {
    draw((i,-1/32)--(i,1/32), black+linewidth(1));
  }
}

