draw((0,0)--(-1/2,-sqrt(3)/2)--(1/2,-sqrt(3)/2)--cycle);
draw((0,0)--(1/2,-sqrt(3)/2)--(1,0)--cycle);
draw((-2,0)--(2,0));
draw((0,-2)--(0,2));
</asy>

