pair A,B,C,D,E,F,G,H,O,X,a,b,c,d,e,f,g;
A=dir(45);
B=dir(90);
C=dir(135);
D=dir(180);
E=dir(-135);
F=dir(-90);
G=dir(-45);
H=dir(0);
O=(0,0);
X=midpoint(A--B);
a=midpoint(B--C);
b=midpoint(C--D);
